import { SettingsPanel } from "@/components/design-for-ai/settings-panel";

export default function Preferences() {
  return (
    <SettingsPanel
      title="Settings"
      sections={[
        {
          id: "notifications",
          label: "Notifications",
          rows: [
            { kind: "toggle", id: "mentions", label: "Mentions", hint: "Someone @mentions you." },
            { kind: "segmented", id: "delivery", label: "Delivery", options: [{ value: "instant", label: "Instantly" }, { value: "daily", label: "Daily" }] },
          ],
        },
      ]}
      initialValues={{ mentions: true, delivery: "daily" }}
      onSave={async (values) => {
        await fetch("/api/settings", { method: "PUT", body: JSON.stringify(values) });
      }}
      accent="#7dd3fc"
    />
  );
}
